import{installCloudLabTheme}from"./chunks/chunk-2O56JSAE.js";import"./chunks/chunk-PZH5C5AP.js";function selectedCloudDemo(url=window.location.href){const demo2=new URL(url).searchParams.get("demo");return demo2==="planet"||demo2==="erosion"?demo2:"flat"}function cloudDemoUrl(demo2,url=window.location.href){const target=new URL(url);target.searchParams.set("demo",demo2==="planet"||demo2==="erosion"?demo2:"flat");return target.href}function mountCloudDemoNavigation(doc=document,url=window.location.href){installCloudLabTheme(doc);if(doc.getElementById("cloud-demo-navigation"))return;const nav=doc.createElement("nav");nav.id="cloud-demo-navigation";nav.setAttribute("aria-label","Noise demos");nav.className="cl-switch cl-switch--floating";const current=selectedCloudDemo(url);for(const[demo2,label]of[["flat","Flat clouds"],["planet","Planet clouds"],["erosion","Erosion terrain"]]){const link=doc.createElement("a");link.textContent=label;link.href=cloudDemoUrl(demo2,url);if(demo2===current){link.setAttribute("aria-current","page");link.addEventListener("click",event=>event.preventDefault())}nav.appendChild(link)}doc.body.appendChild(nav)}mountCloudDemoNavigation();var demo=selectedCloudDemo();if(demo==="erosion"){import("./chunks/noiseErosionTest-WOCUUP3Y.js")}else if(demo==="planet"){import("./chunks/noisePlanetTest-OEM2AVCO.js")}else{import("./chunks/cloudTestThreaded-ZPJ2UTC6.js")}
